    async function loadWorkforceContext(options = {}){
      if (workforceUi.loaded && !options.refresh) return workforceUi;
      if (workforceUi.promise && !options.refresh) return workforceUi.promise;
      const orgId = currentOrgId();
      const branchId = currentBranchId();
      if (!orgId || !window.PlatformAPI?.workforce) return workforceUi;
      workforceUi.promise = (async () => {
        const [configurationResult, profileUsersResult, groupsResult, accessResult, scopesResult, scopeFlagsResult] = await Promise.allSettled([
          window.PlatformAPI.workforce.configuration?.(orgId, branchId),
          window.PlatformAPI.workforce.users?.(orgId, branchId),
          window.PlatformAPI.workforce.resourceGroups?.(orgId, branchId),
          window.PlatformAPI.workforce.accessCatalog?.(orgId),
          window.PlatformAPI.scopes?.list?.(orgId, branchId, { include_disabled:true, includeDisabled:true }),
          window.PlatformAPI.scopes?.flags?.(orgId, branchId)
        ]);
        if (configurationResult.status === 'fulfilled' && configurationResult.value) {
          const source = configurationResult.value?.configuration || configurationResult.value;
          workforceUi.configuration = {
            ...workforceObject(source),
            revision:Number(source?.revision || 0),
            terminology:normalizeWorkforceTerminology(source?.terminology),
            roles:workforceRecords(source, 'roles', 'member_roles')
          };
        }
        if (profileUsersResult.status === 'fulfilled' && profileUsersResult.value) workforceUi.allUsers = workforceRecords(profileUsersResult.value, 'users', 'workforce_users', 'profiles').map(platformUserFromDocument);
        if (groupsResult.status === 'fulfilled') workforceUi.resourceGroups = workforceRecords(groupsResult.value, 'resource_groups', 'groups').map((entry) => ({ ...workforceObject(entry?.data), ...entry }));
        if (accessResult.status === 'fulfilled') {
          workforceUi.accessRoles = workforceRecords(accessResult.value, 'roles', 'access_roles').map((entry) => ({ ...entry }));
          workforceUi.accessCatalog = workforceRecords(accessResult.value, 'apps', 'app_catalog').map((entry) => ({ ...entry }));
          workforceUi.accessPermissionKeys = workforceUniqueIds(accessResult.value?.permission_keys);
        }
        if (scopesResult.status === 'fulfilled') workforceUi.scopeTemplates = workforceRecords(scopesResult.value, 'templates', 'scope_templates').map((entry) => ({ ...workforceObject(entry?.definition), ...entry }));
        if (scopeFlagsResult.status === 'fulfilled') {
          const result = scopeFlagsResult.value || {};
          const explicitFlags = workforceObject(result?.flags || result?.configuration?.flags || result?.scope_flags);
          const catalog = Array.isArray(result?.catalog) ? result.catalog : Array.isArray(result?.scope_catalog) ? result.scope_catalog : [];
          workforceUi.scopeFlags = Object.keys(explicitFlags).length ? explicitFlags : Object.fromEntries(catalog.map((entry) => [workforceText(entry?.id, entry?.template_id), entry?.enabled !== false]).filter(([id]) => id));
        }
        if (tabCrews) {
          const labels = normalizeWorkforceTerminology(workforceUi.configuration.terminology);
          tabCrews.innerHTML = `<i class="fas fa-helmet-safety"></i> ${escapeHtml(labels.resource_group_plural)} and ${escapeHtml(labels.organization_connection_plural)}`;
        }
        workforceUi.loaded = true;
        return workforceUi;
      })().finally(() => { workforceUi.promise = null; });
      return workforceUi.promise;
    }
    async function saveUserInitialGroupMembership(userId, groupId, options = {}){
      const targetGroupId = workforceText(groupId);
      const previousGroupId = workforceText(options.previousGroupId);
      const preserveOtherMemberships = options.preserveOtherMemberships === true;
      if (!userId || !window.PlatformAPI?.workforce?.updateResourceGroup) return;
      if (preserveOtherMemberships && targetGroupId === previousGroupId) return;
      await loadWorkforceContext({ refresh:true });
      const affected = workforceUi.resourceGroups.filter((group) => {
        const id = workforceText(group.id);
        if (preserveOtherMemberships) return id === targetGroupId || id === previousGroupId;
        const current = workforceGroupMembers(group).some((member) => member.user_id === workforceText(userId));
        return current || id === targetGroupId;
      });
      await Promise.all(affected.map((group) => {
        const groupIdValue = workforceText(group.id);
        const currentMembers = workforceGroupMembers(group);
        const currentAssignment = currentMembers.find((member) => member.user_id === workforceText(userId));
        const existingMembers = currentMembers.filter((member) => member.user_id !== workforceText(userId));
        if (groupIdValue === targetGroupId) existingMembers.push(currentAssignment || { user_id:workforceText(userId), role_id:'', is_lead:false, status:'active' });
        const members = existingMembers.map((member) => ({
          user_id:member.user_id,
          role:workforceText(member.role, member.role_id, 'member'),
          is_lead:member.is_lead === true,
          status:workforceText(member.status, 'active')
        }));
        return window.PlatformAPI.workforce.updateResourceGroup(currentOrgId(), currentBranchId(), group.id, {
          expected_revision:Number(group.revision || 0) || undefined,
          members,
          primary_member_user_id:members.find((member) => member.is_lead)?.user_id || null
        });
      }));
      workforceUi.loaded = false;
      await loadWorkforceContext({ refresh:true });
    }
    function formatPhoneUS(raw){
      const d = String(raw || '').replace(/\D/g, '').slice(0, 10);
      if (d.length <= 3) return d;
      if (d.length <= 6) return `(${d.slice(0,3)}) ${d.slice(3)}`;
      return `(${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6)}`;
    }
