        messageFlow: savedMessageFlow && !legacyGeneratedFlow ? savedMessageFlow : documentedMessageFlow,
        sample1: `Hi Jane, this is ${company}. Your appointment is confirmed for tomorrow at 10:00 AM. Reply STOP to opt out.`,
