        return `<div class="sms-field${wide}${invalid}"><label>${escapeHtml(label)}</label><select data-sms-field="${escapeHtml(name)}"${options.disabled ? ' disabled' : ''}>${smsOptionHtml(options.values || [], value)}</select>${helpHtml}</div>`;
