            <div class="wf-group-list">${String(Object.entries(schedulingConfig?.scheduling?.event_types || schedulingConfig?.event_types || {}).map(([eventTypeId, eventType]) => eventAssignmentPolicyHtml(eventTypeId, eventType)).join(''))}</div>
