    async function renderScopeFlags(){
      if (!paneScopeFlags) return;
      const orgId = currentOrgId();
      const branchId = currentBranchId();
      injectCSS('company_scope_flags', `
        .scope-flags-page{max-width:1040px;margin:0 auto;display:grid;gap:16px;padding-top:8px}
        .scope-flags-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}
        .scope-flags-head h3{margin:0 0 4px;font-size:22px;font-weight:1000;color:#101828}
        .scope-flags-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}
        .scope-flags-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}
        .scope-flag-card{position:relative;display:grid;grid-template-columns:5px minmax(0,1fr) auto;gap:12px;align-items:center;border:1px solid #e4e7ec;border-radius:14px;padding:14px;background:#fff;cursor:pointer;transition:border-color .15s ease,box-shadow .15s ease,opacity .15s ease}
        .scope-flag-card:hover{border-color:#cfd4dc;box-shadow:0 8px 22px rgba(16,24,40,.06)}
        .scope-flag-card.off{opacity:.66;background:#f9fafb}
        .scope-flag-color{align-self:stretch;border-radius:999px;background:var(--scope-color,#98a2b3)}
        .scope-flag-copy{display:grid;gap:4px;min-width:0}.scope-flag-copy strong{font-size:14px;color:#101828}.scope-flag-copy span{font-size:11px;line-height:1.4;color:#667085;font-weight:750}
        .scope-flag-switch{width:44px;height:25px;border-radius:999px;background:#d0d5dd;padding:3px;display:flex;align-items:center;transition:.15s ease}.scope-flag-switch:after{content:"";width:19px;height:19px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(16,24,40,.22);transition:.15s ease}.scope-flag-card.on .scope-flag-switch{background:var(--primary,#d93025)}.scope-flag-card.on .scope-flag-switch:after{transform:translateX(19px)}
        @media(max-width:720px){.scope-flags-head{flex-direction:column}.scope-flags-actions{justify-content:flex-start}.scope-flags-grid{grid-template-columns:1fr}}
      `);
      paneScopeFlags.innerHTML = `<div class="cs-note"><i class="fas fa-spinner fa-spin"></i>${(globalThis.PlatformLanguage?.text("settings","m_071e2ad2425d1e"," Loading scope flags...") ?? " Loading scope flags...")}</div>`;
      if (!orgId || !window.PlatformAPI?.scopes?.flags || !window.PlatformAPI?.scopes?.list) {
        paneScopeFlags.innerHTML = `<div class="cs-note">${(globalThis.PlatformLanguage?.text("settings","m_8491c36f8037f0","Scope Flags API is unavailable.") ?? "Scope Flags API is unavailable.")}</div>`;
        return;
      }
      try {
        const [flagsResult, templatesResult] = await Promise.all([
          window.PlatformAPI.scopes.flags(orgId, branchId),
          window.PlatformAPI.scopes.list(orgId, branchId, { include_disabled:true, includeDisabled:true })
        ]);
        let revision = Number(flagsResult?.revision ?? flagsResult?.configuration?.revision ?? 0) || 0;
        let flags = workforceObject(flagsResult?.flags || flagsResult?.configuration?.flags || flagsResult?.scope_flags);
        const catalogSource = flagsResult?.catalog || flagsResult?.scope_catalog || flagsResult?.templates;
        const catalogRecords = Array.isArray(catalogSource) ? catalogSource : (catalogSource && typeof catalogSource === 'object' ? Object.values(catalogSource) : []);
        const templates = (catalogRecords.length ? catalogRecords : workforceArray(templatesResult?.templates || templatesResult?.documents)).map((entry) => {
          const definition = workforceObject(entry?.definition || entry?.data);
          return { ...definition, ...entry, id: workforceText(entry?.id, definition.id), name: workforceText(entry?.name, definition.name, entry?.id) };
        }).filter((template) => template.id);
        const enabledFor = (id) => {
          const value = flags[id];
          if (typeof value === 'boolean') return value;
          if (value && typeof value === 'object') return value.enabled !== false;
          const catalogEntry = templates.find((template) => workforceText(template.id) === workforceText(id));
          if (catalogEntry && typeof catalogEntry.enabled === 'boolean') return catalogEntry.enabled;
          return true;
        };
        const draw = (statusText = '') => {
          paneScopeFlags.innerHTML = `<div class="scope-flags-page">
            <header class="scope-flags-head">
              <div><h3>${(globalThis.PlatformLanguage?.text("settings","m_f6edb5f58a75dd","Scope Flags") ?? "Scope Flags")}</h3><div class="cs-note">${(globalThis.PlatformLanguage?.text("settings","m_803aa694692948","Choose the work templates this company offers. These choices control new proposals and resource capabilities without changing the underlying template definitions.") ?? "Choose the work templates this company offers. These choices control new proposals and resource capabilities without changing the underlying template definitions.")}</div></div>
              <div class="scope-flags-actions"><button type="button" class="cs-btn ghost" data-scope-flags-all>${(globalThis.PlatformLanguage?.text("settings","m_f33bc3906ee6be","Enable all") ?? "Enable all")}</button><button type="button" class="cs-btn primary" data-scope-flags-save><i class="fas fa-save"></i>${(globalThis.PlatformLanguage?.text("settings","m_3eea248894145b"," Save Scope Flags") ?? " Save Scope Flags")}</button></div>
            </header>
            <div class="scope-flags-grid">${String(templates.map((template) => {
              const enabled = enabledFor(template.id);
              return `<label class="scope-flag-card ${enabled ? 'on' : 'off'}" style="--scope-color:${escapeHtml(template.color || '#98a2b3')}">
                <span class="scope-flag-color"></span><span class="scope-flag-copy"><strong>${escapeHtml(template.name || template.id)}</strong><span>${escapeHtml(template.description || 'Available project scope template')}</span></span>
                <input type="checkbox" data-scope-flag="${escapeHtml(template.id)}" ${enabled ? 'checked' : ''} hidden><span class="scope-flag-switch" aria-hidden="true"></span>
              </label>`;
            }).join('') || '<div class="cs-note">No scope templates are configured for this branch.</div>')}</div>
            <div class="cs-note" data-scope-flags-status>${String(escapeHtml(statusText))}</div>
          </div>`;
          paneScopeFlags.querySelectorAll('.scope-flag-card').forEach((card) => {
            const input = card.querySelector('[data-scope-flag]');
            input?.addEventListener('change', () => {
              card.classList.toggle('on', input.checked);
              card.classList.toggle('off', !input.checked);
            });
          });
          paneScopeFlags.querySelector('[data-scope-flags-all]')?.addEventListener('click', () => {
            paneScopeFlags.querySelectorAll('[data-scope-flag]').forEach((input) => {
              input.checked = true;
              input.dispatchEvent(new Event('change'));
            });
          });
          paneScopeFlags.querySelector('[data-scope-flags-save]')?.addEventListener('click', async (event) => {
            const button = event.currentTarget;
            const status = paneScopeFlags.querySelector('[data-scope-flags-status]');
            const nextFlags = {};
            paneScopeFlags.querySelectorAll('[data-scope-flag]').forEach((input) => { nextFlags[input.dataset.scopeFlag] = !!input.checked; });
            button.disabled = true;
            if (status) status.textContent = (globalThis.PlatformLanguage?.text("settings","m_b82c4e12389843","Saving...") ?? "Saving...");
            try {
              const result = await window.PlatformAPI.scopes.saveFlags(orgId, branchId, { expected_revision:revision, flags:nextFlags });
              revision = Number(result?.revision ?? result?.configuration?.revision ?? revision + 1) || revision + 1;
              flags = workforceObject(result?.flags || result?.configuration?.flags || nextFlags);
              window.dispatchEvent(new CustomEvent('fm:scope-flags:updated', { detail:{ revision, flags } }));
              window.dispatchEvent(new CustomEvent('fm:scope-templates:updated', { detail:{ scope_flags:flags } }));
              showToast((globalThis.PlatformLanguage?.text("settings","m_4bb4688766e904","Saved") ?? "Saved"), (globalThis.PlatformLanguage?.text("settings","m_9a58c3655b2a3b","Scope availability updated.") ?? "Scope availability updated."), true);
              draw('Saved.');
            } catch (error) {
              button.disabled = false;
              if (status) status.textContent = error?.message || 'Could not save scope flags.';
              showToast((globalThis.PlatformLanguage?.text("settings","m_c8b7bd7ca69f49","Save failed") ?? "Save failed"), error?.message || 'Could not save scope flags.', false);
            }
          });
        };
        draw();
      } catch (error) {
        paneScopeFlags.innerHTML = `<div class="cs-note">${((v0) => globalThis.PlatformLanguage?.text("settings","m_36ad658d7e23ac",`Could not load scope flags. ${v0}`,{v0}) ?? `Could not load scope flags. ${v0}`)(escapeHtml(error?.message || ''))}</div>`;
      }
    }
